function rows({report}){
 if(!report||typeof report!=='object')throw Error('Invalid Analytics report');
 const data=report.raw??report;if(!data||typeof data!=='object'||Array.isArray(data))throw Error('Invalid Analytics response');
 const rows=data.rows??[];if(!Array.isArray(rows))throw Error('Invalid Analytics rows');const count=data.rowCount??(rows.length===0?0:null);
 if(!Number.isInteger(count)||count<0||count!==rows.length||count>10000)throw Error('Incomplete Analytics report');
 if(!rows.length)return {rows:[]};
 if(data.dimensionHeaders?.length!==1||data.dimensionHeaders[0]?.name!=='country'||data.metricHeaders?.length!==1||data.metricHeaders[0]?.name!=='sessions')throw Error('Unexpected Analytics columns');
 return {rows:rows.map(row=>{const country=row?.dimensionValues?.[0]?.value,n=row?.metricValues?.[0]?.value;if(typeof country!=='string'||!country||typeof n!=='string'||!/^\d+$/.test(n)||!Number.isSafeInteger(Number(n)))throw Error('Invalid Analytics row');return {Country:country,Metric:Number(n)};})};
}

return rows({report:$input.first().json}).rows.map(json=>({json}));
